-- Fakt kartochkalarining ruscha matni — 27-partiya:
-- Abu Mansur al-Moturidiy, Qaffol Shoshiy, Abul Mu'in an-Nasafiy,
-- Abdulxoliq G'ijduvoniy, Pahlavon Mahmud, Ajiniyoz, Amir Temur.

-- ===== Abu Mansur al-Moturidiy =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда родился Абу Мансур аль-Матуриди?', fact_ru = 'Я появился на свет в 870 году. Моё полное имя — Абу Мансур Мухаммад ибн Махмуд аль-Ханафи аль-Матуриди ас-Самарканди. «Аль-Матуриди» в моём имени связано с названием селения Матурид, где я жил.' WHERE id = 1946;
UPDATE fact_cards SET topic_ru = 'Мой труд «Китаб ат-таухид»', question_ru = 'Как называется знаменитый труд Матуриди, посвящённый науке таухида?', fact_ru = 'Я написал труд под названием «Китаб ат-таухид». Эта моя книга посвящена науке таухида, то есть учению о единственности Аллаха.' WHERE id = 1947;
UPDATE fact_cards SET topic_ru = 'Мои другие труды', question_ru = 'Какие ещё труды, кроме «Китаб ат-таухид», написал Матуриди?', fact_ru = 'Я создал немало трудов. Среди них есть и «Китаб аль-усуль», и «Отбор основ шариата», и «Книга о диалектике», и «Наставление».' WHERE id = 1948;
UPDATE fact_cards SET topic_ru = 'Дворец и селение', question_ru = 'По какой причине Матуриди оставил дворец и жил в селении Матурид?', fact_ru = 'Прежде я занимался богословскими науками при дворе государя Насра в Самарканде. Когда Исмаил Самани занял Самарканд, я ушёл из дворца и жил в селении Матурид; когда он звал меня во дворец, я отказался.' WHERE id = 1949;
UPDATE fact_cards SET topic_ru = 'Моя служба имам-хатибом', question_ru = 'В какой должности служил Матуриди в Самарканде и чем ещё он занимался?', fact_ru = 'Я был имам-хатибом в большой соборной мечети Самарканда и трудился в собственном саду. Я воспитал очень многих учеников.' WHERE id = 1950;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Матуриди и где он погребён?', fact_ru = 'Я скончался в 946 году, по хиджре — в 335 году. Меня погребли на самаркандском кладбище Чакардиза.' WHERE id = 1951;

-- ===== Qaffol Shoshiy =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Каффаль Шаши?', fact_ru = 'Я родился в 903 году в Шаше — нынешнем городе Ташкенте, в семье ремесленника. Потому меня и называют Шаши, то есть шашский.' WHERE id = 2266;
UPDATE fact_cards SET topic_ru = 'Моё прозвище «Каффаль»', question_ru = 'Почему Каффалю Шаши дали прозвище «Каффаль»?', fact_ru = 'Я изготовил крохотный замок с ключом весом всего в 0,5 грамма. За это моё мастерство мне и дали прозвище «Каффаль», то есть «Замочник».' WHERE id = 2267;
UPDATE fact_cards SET topic_ru = 'Мои наставники', question_ru = 'У кого учился Каффаль Шаши?', fact_ru = 'Я учился у известного мухаддиса и богослова Хайсама ибн Кулайба. Затем я стал учеником знаменитого имама Абуль Аббаса Ахмада ибн Умара ибн ас-Сурайджи.' WHERE id = 2268;
UPDATE fact_cards SET topic_ru = 'Мои странствия за знанием', question_ru = 'В какие города странствовал Каффаль Шаши?', fact_ru = 'В поисках знания я побывал в Самарканде, Бухаре и Термезе и познакомился с наследием учёных, живших до меня. Затем я совершил долгое странствие по странам арабского Востока и немало времени жил в Багдаде. Исполнял я в халифате и разные должности и поручения.' WHERE id = 2269;
UPDATE fact_cards SET topic_ru = 'Моя учёность и моё достоинство', question_ru = 'В каких науках прославился Каффаль Шаши и почему его называют «Хазрати Имам»?', fact_ru = 'Я мухаддис, факих, языковед и поэт, и меня считали одним из ведущих учёных шафиитского мазхаба. За глубокие познания и великие труды меня называли «Имам аль-Кабир», то есть «Великий имам», а в народе я известен под именем «Хазрати Имам», сокращённо «Хастимом». Я проповедовал шафиитский мазхаб в Мавераннахре, особенно в Шаше, и внёс вклад в распространение религиозных знаний.' WHERE id = 2270;
UPDATE fact_cards SET topic_ru = 'Мои труды и мои стихи', question_ru = 'Какие труды написал Каффаль Шаши?', fact_ru = 'Я написал труды по правоведению и логике: «Нрав судьи», «Одоб аль-бахс» («Правила спора») и «Хусни джадаль» («Красота диалектики»). Эти мои книги прославились в исламском мире. Слагал я и стихи.' WHERE id = 2271;
UPDATE fact_cards SET topic_ru = 'Мой сын Касым', question_ru = 'Кем был сын Каффаля Шаши?', fact_ru = 'Мой сын Абу Али Хасан аль-Касым, как и я, овладел наукой фикха и вырос факихом.' WHERE id = 2272;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Каффаль Шаши и где он погребён?', fact_ru = 'Я скончался в 976 году в родном городе Ташкенте. Позже над моей могилой был построен мавзолей, а вокруг него возник комплекс Хазрати Имам (Хастимом).' WHERE id = 2273;

-- ===== Abul Mu'in an-Nasafiy =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Абуль Муин ан-Насафи?', fact_ru = 'Я родился в 1027 году в древнем городе Насаф. Этот город располагался на месте нынешнего города Карши.' WHERE id = 2108;
UPDATE fact_cards SET topic_ru = 'Моя учёная семья', question_ru = 'В какой семье вырос Абуль Муин ан-Насафи и кем был его дальний предок?', fact_ru = 'Я вырос в просвещённой семье, зрелой в науках и познании. Мой дальний предок Макхуль Насафи был учеником Имама Матуриди.' WHERE id = 2109;
UPDATE fact_cards SET topic_ru = 'На службе науке калама', question_ru = 'В развитие какой науки внёс большой вклад Абуль Муин ан-Насафи?', fact_ru = 'Я занимался наукой калама — эта наука обосновывает исламское вероучение доводами. Я послужил широкому распространению учения матуридия, основанного Абу Мансуром Матуриди.' WHERE id = 2110;
UPDATE fact_cards SET topic_ru = 'Мой труд «Табсират аль-адилля»', question_ru = 'Как называется самый знаменитый труд Абуль Муина ан-Насафи?', fact_ru = 'Одну из самых значительных своих книг я назвал «Табсират аль-адилля». В этом труде я осветил вопросы исламского вероучения по пути Абу Мансура Матуриди.' WHERE id = 2111;
UPDATE fact_cards SET topic_ru = 'Мои знаменитые книги', question_ru = 'Какие труды Абуль Муина ан-Насафи хранятся в библиотеках мира?', fact_ru = 'Я писал книги по исламскому вероучению. Среди моих трудов, хранящихся в библиотеках мира, весьма значительными считаются «Табсират аль-адилля», «Бахр уль-калам» и «Ат-тамхид».' WHERE id = 2112;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Абуль Муин ан-Насафи и где расположен его мавзолей?', fact_ru = 'Я скончался в 1114 году. Мавзолей, возведённый над моей могилой, расположен в селении Ковчин Каршинского района.' WHERE id = 2113;

-- ===== Abdulxoliq G'ijduvoniy =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Абдулхалик Гиждувани?', fact_ru = 'Я родился в 1103 году в Гиждуванском районе Бухарской области. Потому меня и называют Гиждувани.' WHERE id = 2085;
UPDATE fact_cards SET topic_ru = 'Моё детство и путь к знанию', question_ru = 'Какое образование получил Абдулхалик Гиждувани в детстве?', fact_ru = 'Уже в 9 лет я выучил наизусть Священный Коран. Начальное образование я получил в Гиждуване, затем учился в знаменитых бухарских медресе и постигал науку толкования у зрелого учёного по имени Имам Садриддин.' WHERE id = 2086;
UPDATE fact_cards SET topic_ru = 'Мои наставники', question_ru = 'Кто были наставниками Абдулхалика Гиждувани?', fact_ru = 'В 22 года я встретился с прославленным шейхом того времени Ходжой Юсуфом Хамадани, пришедшим в Бухару, и стал его учеником. Ходжу Хызра я считал своим пиром в учении, а Ходжу Юсуфа — пиром беседы и хирки.' WHERE id = 2087;
UPDATE fact_cards SET topic_ru = 'Тарикат ходжаган', question_ru = 'Какому тарикату положил начало Абдулхалик Гиждувани?', fact_ru = 'Я положил начало тарикату ходжей — ходжаган. Я стремился привести тарикат в согласие с сунной Пророка Мухаммада и очистить его от разных новшеств и ложных воззрений.' WHERE id = 2088;
UPDATE fact_cards SET topic_ru = 'Мои восемь правил', question_ru = 'Как называются восемь правил тариката ходжаган?', fact_ru = 'В своём тарикате я разработал восемь рашха-правил: «Хуш дар дам», «Назар бар кадам», «Сафар дар ватан», «Хилват дар анджуман», «Ёдкард», «Бозгашт», «Нигохдошт» и «Ёддошт». В них я призывал держать сердце в чистоте.' WHERE id = 2089;
UPDATE fact_cards SET topic_ru = 'Мои труды', question_ru = 'Какие труды написал Абдулхалик Гиждувани?', fact_ru = 'Я написал труды «Одоби тарикат», «Рисолаи сохибия», «Из речений Ходжи Абдулхалика Гиждувани» и «Рисолаи шейх уш-шуюх хазрати Юсуф Хамадани». Слагал я и суфийские рубаи.' WHERE id = 2090;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Абдулхалик Гиждувани?', fact_ru = 'Я скончался в 1179 году. После моей смерти мой тарикат продолжили мои последователи — Ходжа Ариф Ревгари, а несколько поколений спустя Бахауддин Накшбанд, — и он распространился во многих краях.' WHERE id = 2091;

-- ===== Pahlavon Mahmud =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'В каком году родился Пахлаван Махмуд?', fact_ru = 'Я появился на свет в 1247 году. Вся моя жизнь связана с древним городом Хивой — здесь я занимался ремеслом, творил и возглавлял джаванмардов.' WHERE id = 1960;
UPDATE fact_cards SET topic_ru = 'Хорезмский Хайям', question_ru = 'Каким именем прославился Пахлаван Махмуд благодаря своим философским рубаи?', fact_ru = 'Я слагал философские рубаи, богатые и глубокие по смыслу, крепкие и прекрасные по форме. Благодаря этим рубаи меня прозвали «Хорезмским Хайямом».' WHERE id = 1961;
UPDATE fact_cards SET topic_ru = 'На борцовском поле', question_ru = 'В каких странах Пахлаван Махмуд участвовал в состязаниях по борьбе и всегда побеждал?', fact_ru = 'Я участвовал в состязаниях по борьбе в Иране, Индии и других странах Востока и всякий раз одерживал победу. За всю жизнь мои лопатки не коснулись земли — я был первым борцом страны, предводителем пахлаванов.' WHERE id = 1962;
UPDATE fact_cards SET topic_ru = 'Моё скорняжное ремесло', question_ru = 'Каким ремеслом занимался Пахлаван Махмуд?', fact_ru = 'Я занимался скорняжным ремеслом — шил тулупы — и трудился в собственной лавке. Эта лавка была мне так дорога, что в завещании я просил похоронить меня подле неё.' WHERE id = 1963;
UPDATE fact_cards SET topic_ru = 'Мои труды', question_ru = 'Какая маснави Пахлавана Махмуда упоминается во многих источниках?', fact_ru = 'Я сложил множество рубаи, написал трактаты по богословию, философии и логике. В источниках говорится и о том, что у меня есть маснави под названием «Канз уль-хакаик», то есть «Сокровищница истин».' WHERE id = 1964;
UPDATE fact_cards SET topic_ru = 'Предводитель джаванмардов', question_ru = 'Какое сообщество возглавлял Пахлаван Махмуд в Хиве?', fact_ru = 'Я был главой сообщества футувватчи в Хиве, предводителем джаванмардов. В своих рубаи я изложил правила джаванмардства — нашей целью было противостоять злу и всюду защищать добро.' WHERE id = 1965;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'В каком году умер Пахлаван Махмуд и где он погребён?', fact_ru = 'Я скончался в 1326 году. По моему завещанию ученики похоронили меня возле моей скорняжной лавки.' WHERE id = 1966;

-- ===== Ajiniyoz =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Аджинияз?', fact_ru = 'Я родился в 1824 году в Муйнакском районе. С детства я рос в окружении песен и поэзии каракалпакского народа.' WHERE id = 2014;
UPDATE fact_cards SET topic_ru = 'Мой отец и моё имя', question_ru = 'Кем был отец Аджинияза?', fact_ru = 'Моего отца звали Кусыбай. Потому меня полностью называют Аджинияз, сын Кусыбая.' WHERE id = 2015;
UPDATE fact_cards SET topic_ru = 'Мой псевдоним', question_ru = 'Под каким псевдонимом творил Аджинияз?', fact_ru = 'Свои стихи я писал под псевдонимом «Зивар». В стихотворении я упомянул себя под этим именем: «Есть у каракалпаков и скромный Зивар».' WHERE id = 2016;
UPDATE fact_cards SET topic_ru = 'Мои стихи', question_ru = 'Какие стихи написал Аджинияз?', fact_ru = 'Я написал стихи «Есть у меня народ» и «Будет». В них я воспевал свою любовь к родной земле и к моему народу.' WHERE id = 2017;
UPDATE fact_cards SET topic_ru = 'Каракалпакская поэзия', question_ru = 'Поэтом какого народа является Аджинияз?', fact_ru = 'Я поэт каракалпакского народа. Всю свою жизнь я писал стихи для своего народа.' WHERE id = 2018;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Аджинияз?', fact_ru = 'Я скончался в 1878 году. А стихи мои остались жить в сердце моего народа.' WHERE id = 2019;

-- ===== Amir Temur =====
UPDATE fact_cards SET topic_ru = 'Память обо мне в Узбекистане', question_ru = 'В каком году отмечалось 660-летие со дня рождения Амира Темура?', fact_ru = 'Я скончался в 1405 году. Спустя века, в 1996 году, в Узбекистане широко отмечалось 660-летие со дня моего рождения и в Ташкенте был открыт Государственный музей истории Тимуридов. В Ташкенте, Самарканде и Шахрисабзе поставлены мои памятники — я горжусь тем, что мой народ до сих пор меня помнит.' WHERE id = 1525;
